WITH base AS (SELECT * FROM accounts WHERE customer_id IN (2, 16, 32) AND status IN ('FROZEN', 'CLOSED')), summary AS (SELECT CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 27000 THEN 'mid' ELSE 'low' END AS balance_bucket, ROUND(AVG(balance), 2) AS avg_balance FROM base GROUP BY CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 27000 THEN 'mid' ELSE 'low' END) SELECT balance_bucket, avg_balance FROM summary WHERE avg_balance > 33 ORDER BY avg_balance DESC, balance_bucket DESC LIMIT 5;
